class EmptyInputs(unittest.TestCase):
    def changed(self, file, change):
        d = tempfile.mkdtemp()
        a = TinyRelease()
        folder_a, folder_b = a.write(os.path.join(d, "A")), a.copy().write(os.path.join(d, "B"))
        path = os.path.join(folder_b, file)
        write(path, change(read(path)))
        return compare(folder_a, folder_b)

    def test_a_file_with_nothing_in_it_is_reported_and_the_verdict_is_insufficient_evidence(self):
        for file, empty in ((PROTEIN, ""), (PROTEIN, "\n\n"), (CLINICAL, ""), (MUTATION, "")):
            doc = self.changed(file, lambda text: empty)
            self.assertEqual(doc["verdict"], "Insufficient Evidence", (file, empty))
            self.assertEqual(len(doc["findings"]), 1)
            self.assertIn(f"{file} could not be read", doc["findings"][0]["summary"])
            self.assertIn("is empty", doc["findings"][0]["summary"])

def _priority(findings, repairs, effects):
    """How urgently each suggested fix is needed, sized by its finding's own effect."""
    priority = {}
    for r in repairs:
        fid = r["addresses"][0]
        f = next(x for x in findings if x["id"] == fid)
        sizes = [e["size"] for e in effects.get(fid, {}).values()]
        if not f["affects_analyses"]:
            priority[r["id"]] = {"level": "for the record", "why": "Nothing in the question reads what this finding touches."}
        elif not sizes:
            priority[r["id"]] = {"level": "before use", "why": "An analysis you rely on cannot be rerun until this is resolved."}
        elif "large" in sizes:
            priority[r["id"]] = {"level": "before use", "why": "On its own this finding clearly moves a result you rely on."}
        elif f["kind"] in ("sample_swap", "duplicate"):
            priority[r["id"]] = {"level": "before use", "why": "These samples carry another sample's data. The effect on this "
                                 "result is small or none, but anything else computed from them is wrong too."}
        elif "small" in sizes:
            priority[r["id"]] = {"level": "small effect", "why": "On its own this finding moves no headline number of a result by "
                                 "half a percent or more. Confirm it with the data provider; if you use the release "
                                 "anyway, say so in your methods."}
        else:
            priority[r["id"]] = {"level": "no effect on the result", "why": "It touches samples a result reads, but on its own "
                                 "the result is the same. Fix it when convenient."}
